formulation.statement:
Let $X$ be a topological space.
Assume
\begin{enumerate}
\item $X$ is quasi-compact,
\item $X$ has a basis for the topology consisting of quasi-compact opens, and
\item the intersection of two quasi-compact opens is quasi-compact.
\end{enumerate}
For a subset $T \subset X$ the following are equivalent:
\begin{enumerate}
\item[(a)] $T$ is an intersection of open and closed subsets of $X$, and
\item[(b)] $T$ is closed in $X$ and is a union of connected components of $X$.
\end{enumerate}

source.original_statement_tex:
\label{lemma-closed-union-connected-components}
Let $X$ be a topological space.
Assume
\begin{enumerate}
\item $X$ is quasi-compact,
\item $X$ has a basis for the topology consisting of quasi-compact opens, and
\item the intersection of two quasi-compact opens is quasi-compact.
\end{enumerate}
For a subset $T \subset X$ the following are equivalent:
\begin{enumerate}
\item[(a)] $T$ is an intersection of open and closed subsets of $X$, and
\item[(b)] $T$ is closed in $X$ and is a union of connected components of $X$.
\end{enumerate}

\label{lemma-locally-quasi-finite-fibres}
\begin{slogan}
Finite type morphisms with discrete fibers are quasi-finite.
\end{slogan}
Let $f : X \to S$ be a morphism of schemes.
Assume $f$ is locally of finite type.
Then the following are equivalent
\begin{enumerate}
\item $f$ is locally quasi-finite,
\item for every $s \in S$ the fibre $X_s$ is a discrete topological space, and
\item for every morphism $\Spec(k) \to S$ where $k$ is a field
the base change $X_k$ has an underlying discrete topological space.
\end{enumerate}

