$$
where $j$ is a quasi-compact open immersion and $\pi$ is finite.

\label{lemma-composition-cartesian}
Let $\mathcal{C}$ be a category.
Let $p : \mathcal{S} \to \mathcal{C}$ be a category over $\mathcal{C}$.
\begin{enumerate}
\item The composition of two strongly cartesian morphisms
is strongly cartesian.
\item Any isomorphism of $\mathcal{S}$ is strongly cartesian.
\item Any strongly cartesian morphism $\varphi$ such that $p(\varphi)$
is an isomorphism, is an isomorphism.
\end{enumerate}

\label{lemma-geometrically-reduced-at-point}
\begin{slogan}
Geometric reducedness can be checked on local rings.
\end{slogan}
Let $k$ be a field.
Let $X$ be a scheme over $k$.
Let $x \in X$.
The following are equivalent
\begin{enumerate}
\item $X$ is geometrically reduced at $x$, and
\item the ring $\mathcal{O}_{X, x}$ is geometrically
reduced over $k$ (see
Algebra, Definition \ref{algebra-definition-geometrically-reduced}).
\end{enumerate}

