\label{lemma-koszul-regular-H1-regular}
A $M$-Koszul-regular sequence is $M$-$H_1$-regular.
A Koszul-regular sequence is $H_1$-regular.

\label{lemma-locally-finite-type-surjective-geometric-points}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces
over $S$. Assume $f$ is locally of finite type. The following are equivalent:
\begin{enumerate}
\item $f$ is surjective, and
\item for every algebraically closed field $k$ over $S$ the induced
map $X(k) \to Y(k)$ is surjective.
\end{enumerate}

\label{lemma-sober-local}
Let $X$ be a topological space and let $(X_i)_{i\in I}$ be a covering of $X$.
\begin{enumerate}
\item Suppose $X_i$ is locally closed in $X$ for every $i\in I$. Then, $X$ is
Kolmogorov if and only if $X_i$ is Kolmogorov for every $i\in I$.
\item Suppose $X_i$ is open in $X$ for every $i\in I$. Then, $X$ is
quasi-sober if and only if $X_i$ is quasi-sober for every $i\in I$.
\item Suppose $X_i$ is open in $X$ for every $i\in I$. Then, $X$ is sober if
and  only if $X_i$ is sober for every $i\in I$.
\end{enumerate}

\label{lemma-global-weird-permanence-etale}
Let $f : X \to Y$ and $g : Y \to Z$ be morphisms of schemes.
Assume
\begin{enumerate}
\item $Y$ is integral and geometrically unibranch,
\item $g \circ f$ is \'etale,
\item every irreducible component of $X$ dominates $Y$.
\end{enumerate}
Then $f$ is \'etale and $g$ is \'etale at every point in
the image of $f$.

