formulation.statement:
Let $X$ be an integral locally Noetherian scheme. Let $\mathcal{F}$
be a coherent $\mathcal{O}_X$-module. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is reflexive,
\item for each $x \in X$ one of the following happens
\begin{enumerate}
\item $\mathcal{F}_x$ is a reflexive $\mathcal{O}_{X, x}$-module, or
\item $\text{depth}(\mathcal{F}_x) \geq 2$.
\end{enumerate}
\end{enumerate}

source.original_statement_tex:
\label{lemma-reflexive-depth-2}
Let $X$ be an integral locally Noetherian scheme. Let $\mathcal{F}$
be a coherent $\mathcal{O}_X$-module. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is reflexive,
\item for each $x \in X$ one of the following happens
\begin{enumerate}
\item $\mathcal{F}_x$ is a reflexive $\mathcal{O}_{X, x}$-module, or
\item $\text{depth}(\mathcal{F}_x) \geq 2$.
\end{enumerate}
\end{enumerate}

\label{lemma-refine-by-h}
Let $T$ be a scheme. Let $\{f_i : T_i \to T\}_{i \in I}$ be a family
of morphisms such that $f_i$ is locally of finite presentation for all $i$.
The following are equivalent
\begin{enumerate}
\item $\{T_i \to T\}_{i \in I}$ is an h covering,
\item there is an h covering which refines $\{T_i \to T\}_{i \in I}$, and
\item $\{\coprod_{i \in I} T_i \to T\}$ is an h covering.
\end{enumerate}

