source.original_statement_tex:
\label{lemma-intersect-constructible-with-retrocompact}
Let $X$ be a topological space. Let $T \subset X$ be a subset. Suppose
\begin{enumerate}
\item $T$ is retrocompact in $X$,
\item quasi-compact opens form a basis for the topology on $X$.
\end{enumerate}
Then for a constructible set $E \subset X$ the intersection $E \cap T$ is
constructible in $T$.

\label{proposition-compact}
Let $(A, \text{d})$ be a differential graded algebra. Let $E$ be an
object of $D(A, \text{d})$. Then the following are equivalent
\begin{enumerate}
\item $E$ is a compact object,
\item $E$ is a direct summand of an object of $D(A, \text{d})$
which is represented by a differential graded module $P$ which
has a finite filtration $F_\bullet$ by differential graded submodules
such that $F_iP/F_{i - 1}P$ are finite direct sums of shifts of $A$.
\end{enumerate}

\label{lemma-characterize-quasi-compact}
\begin{reference}
Combination of
\cite[I, p. 75, Lemme 1]{Bourbaki} and
\cite[I, p. 76, Corrolaire 1]{Bourbaki}.
\end{reference}
A topological space $X$ is quasi-compact if and only if the
projection map $Z \times X \to Z$ is closed for
any topological space $Z$.

